def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def intervals(n, cuts):
        ans, start = [], 0
        for p in cuts:
            if start < p:
                ans.append((start, p))
            start = p + 1
        if start < n:
            ans.append((start, n))
        return ans

    rows = intervals(h, sep_rows)
    cols = intervals(w, sep_cols)

    # The compartment with the most non-background cells is the pattern tile.
    source = max(
        ((r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols),
        key=lambda box: sum(
            grid[r][c] != bg
            for r in range(box[0], box[1])
            for c in range(box[2], box[3])
        )
    )
    r0, r1, c0, c1 = source
    tile = [grid[r][c0:c1] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for a, b in rows:
        for c, d in cols:
            if (b - a, d - c) == (len(tile), len(tile[0])):
                for i in range(len(tile)):
                    for j in range(len(tile[0])):
                        out[a + i][c + j] = tile[i][j]
    return out
